namespace ghidra.feature.vt.gui.wizard.session;

using static ghidra.framework.main.DataTreeDialogType;





using docking.widgets;
using ghidra.feature.vt.api.main;
using ghidra.feature.vt.gui.task;
using ghidra.framework.main;
using ghidra.framework.model;
using ghidra.program.model.listing;
using ghidra.util;
using ghidra.util.task;

public class VTWizardUtils {

	private static class DomainFileBox {
		DomainFile df;
	}

	public static readonly DomainFileFilter VT_SESSION_FILTER =
		new DefaultDomainFileFilter(typeof(VTSession), true);

	public static DomainFile chooseProgramFile(Component parent, string domainIdentifier,
			DomainFile fileToSelect) {
		DataTreeDialog dataTreeDialog = new DataTreeDialog(parent,
			"Choose " + domainIdentifier, OPEN, new DefaultDomainFileFilter(typeof(Program), true));
		DomainFileBox box = new DomainFileBox();
		dataTreeDialog.addOkActionListener(new _Anon_ActionListener_1());
		dataTreeDialog.selectDomainFile(fileToSelect);
		dataTreeDialog.showComponent();
		return box.df;
	}

	static public bool askUserToSave(Component parent, DomainFile domainFile) {

		string filename = domainFile.getName();
		int result = OptionDialog.showYesNoDialog(parent, "Save Version Tracking Changes?",
			"<html>Unsaved Version Tracking changes found for session: " +
				HTMLUtilities.escapeHTML(filename) + ".  <br>" +
				"Would you like to save these changes?");

		bool doSave = result == OptionDialog.YES_OPTION;
		if (doSave) {
			SaveTask saveTask = new SaveTask(domainFile);
			new TaskLauncher(saveTask, parent);
			return saveTask.didSave();
		}
		return false;
	}

	// returns false if the operation was cancelled or the user tried to save but it failed.
	static public bool askUserToSaveBeforeClosing(Component parent, DomainFile domainFile) {

		string filename = domainFile.getName();
		int result = OptionDialog.showYesNoCancelDialog(parent, "Save Version Tracking Changes?",
			"<html>Unsaved Version Tracking changes found for session: " +
				HTMLUtilities.escapeHTML(filename) + ".  <br>" +
				"Would you like to save these changes?");

		if (result == OptionDialog.CANCEL_OPTION) {
			return false;
		}
		bool doSave = result == OptionDialog.YES_OPTION;
		if (doSave) {
			SaveTask saveTask = new SaveTask(domainFile);
			new TaskLauncher(saveTask, parent);
			return saveTask.didSave();
		}
		return true;
	}


	internal class _Anon_ActionListener_1 : ActionListener
	{

			/* @Override */
			public void actionPerformed(ActionEvent e) {
				box.df = dataTreeDialog.getDomainFile();
				if (box.df == null) {
					return;
				}
				dataTreeDialog.close();
			}
		
	}

}
